#[derive(Debug,Default)]struct Queries{counter:Arc<AtomicUsize>,bodies:AtomicUsize,compatibility:AtomicUsize,fail:AtomicBool}
impl Queries{fn admitted<T>(&self,run:impl FnOnce(&dm_syntax::SettingAdmission<'_>)->Result<T,BodySyntaxFailure>)->Result<T,BodySyntaxFailure>{let poll=||Ok(());let a=dm_syntax::SettingAdmission::new(&self.counter,64*1024*1024,&poll);let result=run(&a);if matches!(&result,Err(BodySyntaxFailure::Operational(_))){return result}if let Some(actual)=a.take_operational_error(){return Err(BodySyntaxFailure::Operational(actual))}result}}
impl SettingExpressionQueries for Queries{
 fn with_declaration_admission(&self,operation:&mut dyn FnMut(&dm_syntax::SettingAdmission<'_>)->Result<(),BodySyntaxFailure>)->Result<(),BodySyntaxFailure>{self.admitted(|a|operation(a))}
 fn expression(&self,input:&SettingExpressionInput<'_>)->Result<dm_syntax::SettingExpression,BodySyntaxFailure>{self.admitted(|a|input.prepare(a))}
 fn statements(&self,input:&mut dm_tree::frontend::SettingStatementsInput<'_,'_>)->Result<Arc<dm_tree::frontend::StatementBody>,BodySyntaxFailure>{self.admitted(|a|input.prepare(a))}
}
impl BodySyntaxQueries for Queries{
 fn syntax(&self,input:&Arc<BodySyntaxInput>)->Result<Arc<BodySyntax>,dm_tree::frontend::Diagnostic>{self.compatibility.fetch_add(1,Ordering::Relaxed);input.parse().map(Arc::new)}
 fn syntax_checked(&self,input:&Arc<BodySyntaxInput>)->Result<Arc<BodySyntax>,BodySyntaxFailure>{self.bodies.fetch_add(1,Ordering::Relaxed);if self.fail.load(Ordering::Acquire){return Err(BodySyntaxFailure::Operational(io::Error::from_raw_os_error(1450)))}self.admitted(|a|input.parse_with_setting_admission(a).map(Arc::new))}
}

struct ActualPages<'a>{raw:&'a crate::captured_raw_policy::CapturedRawPolicy,busy:std::cell::Cell<bool>,configuration:Option<&'a crate::captured_raw_file::Config>,passes:std::cell::Cell<usize>,fail:bool}
impl crate::reactive_raw_policy_pages::RawPolicyPages for ActualPages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{if self.fail{return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}self.passes.set(self.passes.get()+1);if self.busy.replace(true){return Err(Failure::Operational(io::Error::new(io::ErrorKind::InvalidInput,"nested original page loan")))}struct Reset<'a>(&'a std::cell::Cell<bool>);impl Drop for Reset<'_>{fn drop(&mut self){self.0.set(false)}}let _reset=Reset(&self.busy);for file in self.raw.tree.files.iter().filter(|file|crate::tree::CODE_DM.matches(file)){if self.configuration.is_some_and(|c|c.policy_path_exempt("derived_reads","",&file.rel)){continue}if !visit(&file.rel,crate::captured_raw_file::RawPolicyViews::from_source(file))?{return Ok(false)}}Ok(true)}}
const SEED:&str=r#"#define TRACKED(T,V)
#define PUBLISHED_BY(T,V,K)
/datum/foreign
    var/far
/obj/probe
    var/value
    var/missing
    var/mutable
    var/link
/obj/probe/derived()
    return list(drawn_from(nameof(value), rel(nameof(link), nameof(/datum/foreign::far))))
/obj/probe/draw()
    return missing
/obj/probe/on_state_changed()
    return
/obj/probe/ui_data()
    return list(mutable, value)
/obj/probe/mutate()
    mutable = 7
/obj/probe/child/draw()
    // ALLOW(derived_reads): intentional fixture read kept by the original policy
    return missing
/mob/probe
    var/custom_health
/mob/probe/life_hud()
    return custom_health
"#;
fn rows(sites:&[crate::lint::Site])->Vec<(String,String,u32,String,String,String)>{sites.iter().map(|s|(s.rule.clone(),s.rel.clone(),s.line,s.msg.clone(),s.key.clone(),s.ident.clone())).collect()}
fn allowed(rows:&[crate::lint::AllowUse])->Vec<(String,u32,String,String)>{rows.iter().map(|s|(s.rel.clone(),s.line,s.name.clone(),s.code.clone())).collect()}
