 let mut registry=crate::lint::Registry::default();original::register(&mut registry);let engine=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),raw:true,lints:vec!["derived_reads".to_owned()],..Default::default()}).unwrap();let old=engine.run_one(engine.reg.find("derived_reads").unwrap());assert!(old.internal_error.is_none(),"{:?}",old.internal_error);
 let order_budget=crate::captured_generator_budget::Budget::new(4*1024*1024).unwrap();let order=crate::captured_reactive_reads::original_include_order(&inputs,&root,&order_budget).unwrap();let types=crate::sem::gen::test_only_types(&engine.tree);let global_budget=crate::captured_generator_budget::Budget::new(128*1024*1024).unwrap();let globals=crate::captured_reactive_reads::globals_native(&inputs,&root,&global_budget,&poll,&borrower).unwrap();let calls=std::cell::Cell::new(0);let provider=|action:&mut dyn FnMut(&crate::captured_reactive_reads::GlobalResult)->Result<bool,Failure>|{assert!(selected.passes.get()>0,"old raw Model phase must precede the real Globals question");calls.set(calls.get()+1);action(&globals)};let before=queries.bodies.load(Ordering::Relaxed);let budget=crate::captured_generator_budget::Budget::new(128*1024*1024).unwrap();let native=crate::captured_reactive_reads::derived_reads_data_from_pages(&inputs,&root,&selected,&pages,&order,&types,&budget,&provider,&poll,&borrower).unwrap();
 assert_eq!(rows(native.sites()),rows(&old.run.sites));if exempt{assert_eq!(old.run.sites.iter().filter(|site|site.rule=="untracked_ui_read").count(),2,"exempt uncompiled raw setter names must still defeat the mutable-value exemption");}assert_eq!(allowed(native.allow_used()),allowed(&old.allow_used));assert_eq!(native.source_text().iter().map(String::as_str).collect::<Vec<_>>(),old.run.sites.iter().map(|site|crate::util::normalize_ws(engine.tree.get(&site.rel).unwrap().raw().line(site.line as usize))).collect::<Vec<_>>().iter().map(String::as_str).collect::<Vec<_>>());assert_eq!(native.generated_is_stale(),old.text.contains("code/_generated/reads.dm is stale"));assert_eq!(native.post_judge_message(),stale.then_some("derived_reads: code/_generated/reads.dm is stale; run `analyze gen derived_reads` and commit it\n"));

 let scope=engine.scopes.for_lint(native.metadata().name,native.metadata().group);let native_report=crate::policy_finish::finish_report(native.metadata(),&scope,&native,crate::lint::Run{sites:native.sites().to_vec(),notes:Vec::new()},native.allow_used().to_vec(),crate::policy_finish::Timing::default(),&root,&None,true,|_,_,_|false,|_,text|{if let Some(message)=native.post_judge_message(){text.push_str(message);true}else{false}});assert_eq!(native_report.text,old.text,"complete common rendering, hard-rule judgments and exact post-judge output");assert_eq!(native_report.failed,old.failed);assert!(native_report.internal_error.is_none());
 let rules:native_rules::Rules=native.sites().iter().map(|s|s.rule.as_str()).collect();assert_eq!(rules.len(),6,"every real rule must be observed, not an empty/falsified report: {rules:?}");assert!(!native.allow_used().is_empty());assert_eq!(queries.bodies.load(Ordering::Relaxed),before,"raw judge/generator must not demand a second AST after genuine native Globals");assert_eq!(queries.compatibility.load(Ordering::Relaxed),0);assert_eq!(calls.get(),1);assert!(!pages.busy.get());

